"""Educational vital-signs toolkit: mean arterial pressure (MAP)."""


def map_mmhg(sbp, dbp):
    """Return mean arterial pressure in mmHg, rounded to 1 decimal.

    MAP = (SBP + 2 * DBP) / 3

    Raises:
        ValueError: if dbp >= sbp, either value is non-positive,
            or sbp > 300 or dbp > 200.
    """
    for name, value in (("sbp", sbp), ("dbp", dbp)):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise ValueError(f"{name} must be a number")
        if value <= 0:
            raise ValueError(f"{name} must be positive, got {value}")
    if dbp >= sbp:
        raise ValueError(f"dbp ({dbp}) must be lower than sbp ({sbp})")
    if sbp > 300:
        raise ValueError(f"sbp ({sbp}) exceeds maximum of 300 mmHg")
    if dbp > 200:
        raise ValueError(f"dbp ({dbp}) exceeds maximum of 200 mmHg")
    return round((sbp + 2 * dbp) / 3, 1)


def classify_map(value):
    """Classify a MAP value: 'low' below 65, 'normal' 65-110, 'high' above 110."""
    if not isinstance(value, (int, float)) or isinstance(value, bool):
        raise ValueError("value must be a number")
    if value < 65:
        return "low"
    if value <= 110:
        return "normal"
    return "high"

