import pytest

from map_mmhg import classify_map, map_mmhg


def test_typical_120_over_80():
    assert map_mmhg(120, 80) == 93.3


def test_rejects_dbp_equal_to_sbp():
    with pytest.raises(ValueError):
        map_mmhg(120, 120)


def test_rejects_dbp_above_sbp():
    with pytest.raises(ValueError):
        map_mmhg(100, 130)


@pytest.mark.parametrize(
    ("value", "expected"),
    [
        (64.9, "low"),
        (65.0, "normal"),
        (110.0, "normal"),
        (110.1, "high"),
    ],
)
def test_classification_boundaries(value, expected):
    assert classify_map(value) == expected


def test_negative_sbp():
    with pytest.raises(ValueError):
        map_mmhg(-120, 80)


def test_negative_dbp():
    with pytest.raises(ValueError):
        map_mmhg(120, -80)


def test_zero_input():
    with pytest.raises(ValueError):
        map_mmhg(0, 80)


def test_sbp_upper_limit():
    with pytest.raises(ValueError):
        map_mmhg(301, 80)
    assert map_mmhg(300, 80) == 153.3


def test_dbp_upper_limit():
    with pytest.raises(ValueError):
        map_mmhg(250, 201)

